rguments":{"command":"python3 << 'EOF'\n# Let me look at more pages in the December bulletin to see if there's monthly breakdown\n\nimport json\n\nwith open('/app/resources/treasury_bulletin_2021_12.json') as f:\n    d = json.load(f)\n\ndoc = d.get('document', {})\nelements = doc.get('elements', [])\n\n# Search for tables containing monthly data for July, Aug, Sept in 2021\nfor e in elements:\n    content = e.get('content', '')\n    if content and ('july' in content.lower() or 'august' in content.lower()) and 'table' in content.lower():\n        page_id = e.get('bbox', [{}])[0].get('page_id', 'N/A')\n        if 'corporate' in content.lower() or 'income' in content.lower() or 'receipt' in content.lower():\n            print(f\"Page {page_id}:\")\n            print(content[:2000])\n            print('---')\n            print()\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
